CREATE TABLE mesadas_pension (id INT UNSIGNED NOT NULL AUTO_INCREMENT,perfil_id INT UNSIGNED NOT NULL,mes TINYINT UNSIGNED NOT NULL,comprobante_id INT UNSIGNED NOT NULL,datos LONGTEXT NOT NULL,vigente TINYINT UNSIGNED NULL DEFAULT 1,ingreso_id INT UNSIGNED NOT NULL,aporte_id INT UNSIGNED NOT NULL,actor_id INT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY mesada_actual(perfil_id,mes,vigente),CONSTRAINT mesada_perfil_fk FOREIGN KEY(perfil_id) REFERENCES perfiles_renta(id),CONSTRAINT mesada_documento_fk FOREIGN KEY(comprobante_id) REFERENCES comprobantes_pension(id),CONSTRAINT mesada_ingreso_fk FOREIGN KEY(ingreso_id) REFERENCES movimientos_ingresos(id),CONSTRAINT mesada_aporte_fk FOREIGN KEY(aporte_id) REFERENCES movimientos_ingresos(id),CONSTRAINT mesada_json CHECK(JSON_VALID(datos)),CONSTRAINT mesada_mes CHECK(mes BETWEEN 1 AND 12)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
